import math
from fractions import Fraction

def combinations(n, k):
    if k < 0 or k > n:
        return 0
    # Use math.comb if available (Python 3.8+), otherwise use factorials
    try:
        return math.comb(n, k)
    except AttributeError:
        if k == 0 or k == n:
            return 1
        if k > n // 2:
            k = n - k

        res = 1
        for i in range(k):
            res = res * (n - i) // (i + 1)
        return res

def solve():
    solutions = []
    # Iterate n from 5 up to 199 (since < 200)
    for n in range(5, 200):
        if math.gcd(n, 6) != 1:
            continue

        # Determine the range for a
        a_min = math.ceil(n / 3)
        a_max = math.floor((n - 1) / 2)

        is_solution = True

        if a_min > a_max:
            # Vacuously true, but generally unlikely for n>=5 with gcd(n, 6)=1
            is_solution = True
        else:
            for a in range(int(a_min), int(a_max) + 1):
                # K = n - 2a
                K = n - 2 * a

                # N = a - 1
                N = a - 1

                # R = n - 2a - 1 = K - 1
                R = K - 1

                # We check if C(N, R) is divisible by K
                # C(a-1, n-2a-1) is divisible by n-2a

                if K <= 0:
                    # Should not happen given a_max <= (n-1)/2 => 2a <= n-1 => n-2a >= 1
                    # But as a safeguard, if K<=0, the condition is ill-defined or trivial.
                    is_solution = False
                    break

                C_val = combinations(N, R)

                if C_val % K != 0:
                    is_solution = False
                    # print(f"Failed for n={n}, a={a}. K={K}. C({N},{R})={C_val}. {C_val}%{K} = {C_val % K}")
                    break

        if is_solution:
            solutions.append(n)

    return solutions

solutions = solve()
print(solutions)
